# Step 2: Define the vision LLM with LLaMA

import base64
from ibm_watsonx_ai.foundation_models import ModelInference
from ibm_watsonx_ai import Credentials

def vision_llm(system_msg, prompt_txt, image_path):
    model_id = 'meta-llama/llama-4-maverick-17b-128e-instruct-fp8'
    project_id = "skills-network"
    credentials = Credentials(url = "https://us-south.ml.cloud.ibm.com")
    generate_params = {"max_tokens": 300}

    ### Step 2.1: Define the model by ModelInference
    model = ModelInference(model_id = model_id,
                           credentials = credentials,
                           project_id = project_id,
                           params  = generate_params)

    ### Step 2.2: Encode the input image to a base64 string
    with open(image_path, "rb") as img_file:
        img_base64 = base64.b64encode(img_file.read()).decode("utf-8")

    ### Step 2.3: Define the messages for the model
    messages = [{"role": "system", "content": system_msg},
                {"role": "user", "content": [{"type": "text", "text": prompt_txt},
                                             {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{img_base64}"}}]}]

    ### Step 2.4: Get the response for the messages
    response = model.chat(messages = messages)

    return response["choices"][0]["message"]["content"]

# Step 3: Design and validate prompts for the vision LLM

def image_caption_prompt_template(food_name):
    # Step 3.1: Design the prompts
    image_caption_system_msg = """You are an expert food image analyst.
                                  Your task is to generate accurate, concise, and visually grounded descriptions of food images.
                                  Focus only on what is visible in the image. Do not guess ingredients or cooking steps that are not clearly observable."""

    image_caption_prompt_txt = f"""Analyze the food image carefully and generate a high-quality caption.
                                   The expected dish is: {food_name}

                                   Your caption must:
                                   - Describe the dish appearance (color, texture, arrangement, plating)
                                   - Identify visible ingredients only
                                   - Mention cooking style if clearly inferable (e.g., baked, fried, grilled)
                                   - Be concise (2–4 sentences max)
                                   - Avoid speculation or assumptions not supported by the image

                                   Return only the caption."""

    return image_caption_system_msg, image_caption_prompt_txt

# Step 3.2: Get prompts
