# Step 2.1: Prompt template function
def review_context_image_caption_prompt_template(reviews):
    review_context_image_caption_system_msg = """You are a culinary expert and multimodal food analyst.
                                                 Your task is to generate a concise and accurate description of a food image, using both:
                                                 1. Visual information from the image
                                                 2. Context from user reviews
                                                 You must ensure the final description is consistent with the sentiment and details mentioned in the reviews.
                                                 Do not invent details not supported by either the image or the reviews."""

    review_context_image_caption_prompt_txt = f"""You are given:
                                                  - A food image
                                                  - User review context about the dish
                                                  User reviews: {reviews}

                                                  Task: Write a concise 2–4 sentence description of the food image that:
                                                  - Matches what is visible in the image
                                                  - Aligns with the sentiment expressed in the reviews
                                                  - Highlights key ingredients, presentation, and dining experience cues if relevant
                                                  - Avoids hallucination or adding unsupported details

                                                  Return only the final description."""

    return review_context_image_caption_system_msg, review_context_image_caption_prompt_txt

# Step 2.2: Get reviews text (combine title + review text for richer context)
